var isCycle = false; var iCurrent = -1; var frmName = "0"; function enterToTab() { try { var c = document.activeElement; if (c == null) { return false } if (window.event.keyCode == 13) { switch (c.tagName) { case "INPUT": handleInput(c); break; case "SELECT": handleSelect(c); break; default: } } } catch (d) { } } function handleInput(b) { switch (b.type) { case "text": case "password": case "checkbox": case "radio": case "file": moveFocusToNextElement(b); break; case "submit": case "button": if (isHandleSubmit(b)) { handleSubmit(b); focusOnNextElement(document.forms[frmName].elements, iCurrent - 1); break } moveFocusToNextElement(b); break; default: } } function handleSelect(b) { moveFocusToNextElement(b) } function handleTextarea(b) { moveFocusToNextElement(b) } function moveFocusToNextElement(e) { var g = document.forms[frmName].elements, h = -1; for (var f = 0; f < g.length; f++) { if (g[f] == e) { h = f } if (h > -1 && h + 1 < g.length) { focusOnNextElement(g, h) } } } function focusOnNextElement(h, f) { var j = h; var i = f; while (j[f + 1].type == "hidden" || j[f + 1].disabled || j[f + 1].readOnly == true || j[f + 1].style.display == "none") { f++; if (f + 1 == j.length) { if (isCycle) { focusOnNextElement(j, -1) } return } } iCurrent = f + 1; if ($(j[iCurrent]).attr("class") != undefined) { if ($(j[iCurrent]).attr("class").toLowerCase() != "datetimebox") {  $(j[iCurrent]).focus() } else { var i = document.forms[frmName].elements; if (iCurrent > -1 && iCurrent + 1 < i.length) { focusOnNextElement(j, iCurrent) } } } else {   $(j[iCurrent]).focus() } try { window.event.keyCode = 0; window.event.returnValue = false } catch (g) { } return } function handleSubmit(b) { b.click(); return } function isHandleSubmit(c) { var d = false; if (c != null && (c.id.toUpperCase() == "SUBMIT" || c.name.toUpperCase() == "SUBMIT" || c.isSubmit)) { d = true } return d } function initEnter2Tab() { document.forms[0].onkeydown = function b() { enterToTab() }; if (document.forms[0].elements != null) { focusOnNextElement(document.forms[0].elements, -1) } } $(document).ready(function () { initEnter2Tab() });